15	test('normalizeId handles edge cases', () => {
16	  assert.equal(normalizeId(''), '');
17	  assert.equal(normalizeId('   '), '');
18	  assert.equal(normalizeId(null), '');
19	  assert.equal(normalizeId(undefined), '');
20	});
